assert json.loads(Path("api-contract.json").read_text()) == expected_contract
contract = expected_contract
request_spec = contract["request"]
def materialize(value, bindings):
    if isinstance(value, str) and value.startswith("$"):
        return bindings[value[1:]]
    if isinstance(value, dict):
        return {key: materialize(item, bindings) for key, item in value.items()}
    if isinstance(value, list):
        return [materialize(item, bindings) for item in value]
    return value
def response(rows, next_page):
    result = {}
    for path, value in ((contract["response"]["records_pointer"], rows), (contract["response"]["next_page_pointer"], next_page)):
        current = result
        for part in path[:-1]:
            current = current.setdefault(part, {})
        current[path[-1]] = value
    return result
def run_pages(owner, pages):
