        assert method == request_spec["method"]
        assert path == request_spec["path"]
        assert body == materialize(request_spec["json_body"], {"owner_id": owner, "page_token": cursor})
        calls.append((method, path, copy.deepcopy(body)))
        assert cursor in pages
        rows, next_page = pages[cursor]
        return response(rows, next_page)
    result = list_records(request, owner)
    return result, calls
